using System.Collections.ObjectModel;
using System.ComponentModel;
using System.IO;
using System.Runtime.CompilerServices;
using System.Windows.Input;
using System.Windows.Data;
using Microsoft.Win32;
using SoftwareCatalog.Core;
using SoftwareCatalog.Core.Abstractions;
using SoftwareCatalog.Core.Domain;
using SoftwareCatalog.Scanner;
using SoftwareCatalog.Infrastructure.Settings;

namespace SoftwareCatalog.UI.ViewModels;
public sealed class MainViewModel : INotifyPropertyChanged
{
    private readonly IScanCatalogRepository _repository; private readonly IProductCatalogRepository _products; private readonly IPortablePathResolver _paths; private readonly CatalogScanner _scanner; private readonly ProductCatalogService _catalog; private readonly UpdateBatchService _batch; private readonly AppSettings _settings; private readonly UpdateDownloadDiscoveryService _downloads; private readonly DownloadService _downloader; private readonly IAppPathService _appPaths; private readonly IDownloadHistoryRepository _history; private CancellationTokenSource? _cts; private ScanRoot? _selected; private SoftwareProduct? _selectedProduct; private string _statusFilter = "Все"; private string _statusText = "Готово";
    public MainViewModel(IScanCatalogRepository repository, IProductCatalogRepository products, IPortablePathResolver paths, CatalogScanner scanner, ProductCatalogService catalog, UpdateBatchService batch, AppSettings settings, UpdateDownloadDiscoveryService downloads, DownloadService downloader, IAppPathService appPaths, IDownloadHistoryRepository history) { _repository = repository; _products = products; _paths = paths; _scanner = scanner; _catalog = catalog; _batch = batch; _settings = settings; _downloads = downloads; _downloader = downloader; _appPaths = appPaths; _history = history; ProductsView = CollectionViewSource.GetDefaultView(Products); ProductsView.Filter = item => item is SoftwareProduct product && MatchesFilter(product); AddFolderCommand = new AsyncCommand(AddFolderAsync); ChangeFolderCommand = new AsyncCommand(ChangeFolderAsync); RemoveFolderCommand = new AsyncCommand(RemoveFolderAsync); ScanCommand = new AsyncCommand(ScanAsync); CheckSelectedCommand = new AsyncCommand(CheckSelectedAsync); CheckAllCommand = new AsyncCommand(CheckAllAsync); DownloadUpdateCommand = new AsyncCommand(DownloadUpdateAsync); SetWinGetBindingCommand = new AsyncCommand(() => SetBindingAsync("WinGet", "Введите WinGet package ID:")); SetGitHubBindingCommand = new AsyncCommand(() => SetBindingAsync("GitHub", "Введите GitHub owner/repository:")); ClearWinGetBindingCommand = new AsyncCommand(() => ClearBindingAsync("WinGet")); ClearGitHubBindingCommand = new AsyncCommand(() => ClearBindingAsync("GitHub")); CancelCommand = new RelayCommand(() => _cts?.Cancel()); _ = LoadAsync(); }
    public ObservableCollection<ScanRoot> ScanRoots { get; } = []; public ObservableCollection<InstallerFile> Files { get; } = []; public ObservableCollection<SoftwareProduct> Products { get; } = []; public ICollectionView ProductsView { get; } public string[] StatusFilters { get; } = ["Все", "Есть обновления", "Актуальные", "Проблемы"]; public string SelectedStatusFilter { get => _statusFilter; set { _statusFilter = value; OnChanged(); ProductsView.Refresh(); } } public ObservableCollection<InstallerFile> ProductFiles { get; } = []; public ScanRoot? SelectedScanRoot { get => _selected; set { _selected = value; OnChanged(); OnChanged(nameof(SelectedRootAvailability)); } } public SoftwareProduct? SelectedProduct { get => _selectedProduct; set { _selectedProduct = value; OnChanged(); _ = RefreshProductFilesAsync(); } } public string SelectedRootAvailability => SelectedScanRoot is null ? "" : _paths.GetAvailability(SelectedScanRoot) == ScanRootAvailability.Available ? "Доступна" : "Не найдена"; public string StatusText { get => _statusText; private set { _statusText = value; OnChanged(); } } public bool StoreRelativeToApplication { get; set; } public bool IsScanning { get; private set; } public ICommand AddFolderCommand { get; } public ICommand ChangeFolderCommand { get; } public ICommand RemoveFolderCommand { get; } public ICommand ScanCommand { get; } public ICommand CheckSelectedCommand { get; } public ICommand CheckAllCommand { get; } public ICommand DownloadUpdateCommand { get; } public ICommand SetWinGetBindingCommand { get; } public ICommand SetGitHubBindingCommand { get; } public ICommand ClearWinGetBindingCommand { get; } public ICommand ClearGitHubBindingCommand { get; } public ICommand CancelCommand { get; }
    private bool MatchesFilter(SoftwareProduct product) => ProductStatusFilter.Matches(product, SelectedStatusFilter);
    private async Task LoadAsync() { foreach (var root in await _repository.GetScanRootsAsync(CancellationToken.None)) ScanRoots.Add(root); await RefreshFilesAsync(); await RefreshProductsAsync(); }
    private async Task AddFolderAsync() { var dialog = new OpenFolderDialog(); if (dialog.ShowDialog() != true) return; var kind = StoreRelativeToApplication ? ScanRootPathKind.RelativeToApplication : ScanRootPathKind.Absolute; var root = await _repository.AddScanRootAsync(_paths.ToStoredPath(dialog.FolderName, kind), kind, true, CancellationToken.None); ScanRoots.Add(root); SelectedScanRoot = root; }
    private async Task ChangeFolderAsync() { if (SelectedScanRoot is null) return; var dialog = new OpenFolderDialog(); if (dialog.ShowDialog() != true) return; var root = SelectedScanRoot; await _repository.UpdateScanRootAsync(root.Id, _paths.ToStoredPath(dialog.FolderName, root.PathKind), root.PathKind, CancellationToken.None); var index = ScanRoots.IndexOf(root); var updated = root with { StoredPath = _paths.ToStoredPath(dialog.FolderName, root.PathKind), UpdatedUtc = DateTimeOffset.UtcNow }; ScanRoots[index] = updated; SelectedScanRoot = updated; }
    private async Task RemoveFolderAsync() { if (SelectedScanRoot is null) return; await _repository.RemoveScanRootAsync(SelectedScanRoot.Id, CancellationToken.None); ScanRoots.Remove(SelectedScanRoot); SelectedScanRoot = null; await RefreshFilesAsync(); }
    private async Task ScanAsync() { if (SelectedScanRoot is null || IsScanning) return; IsScanning = true; _cts = new(); StatusText = "Сканирование..."; try { var result = await _scanner.ScanAsync(SelectedScanRoot, new Progress<ScanProgress>(p => StatusText = $"Файлов: {p.Discovered} | Обработано: {p.Processed} | Ошибок: {p.Errors}"), _cts.Token); await _catalog.RegroupAsync(_cts.Token); StatusText = result.Completed ? $"Завершено. Файлов: {result.ProcessedFiles}; ошибок: {result.Errors.Count}" : "Сканирование отменено."; await RefreshFilesAsync(); await RefreshProductsAsync(); } catch (OperationCanceledException) { StatusText = "Операция отменена."; } finally { IsScanning = false; _cts.Dispose(); _cts = null; } }
    private async Task RefreshFilesAsync() { Files.Clear(); foreach (var file in await _repository.GetInstallersAsync(CancellationToken.None)) Files.Add(file); }
    private async Task RefreshProductsAsync() { Products.Clear(); foreach (var product in await _products.GetProductsAsync(CancellationToken.None)) Products.Add(product); }
    private async Task RefreshProductFilesAsync() { ProductFiles.Clear(); if (SelectedProduct is null) return; foreach (var file in await _products.GetInstallersForProductAsync(SelectedProduct.Id, CancellationToken.None)) ProductFiles.Add(file); }
    private async Task CheckSelectedAsync() { if (SelectedProduct is null) return; await CheckAsync([SelectedProduct]); }
    private async Task CheckAllAsync() => await CheckAsync(Products);
    private async Task DownloadUpdateAsync() { if (SelectedProduct is null || SelectedProduct.UpdateStatus != UpdateStatus.UpdateAvailable || IsScanning) return; IsScanning = true; _cts = new(); var product = SelectedProduct; var started = DateTimeOffset.UtcNow; DownloadCandidate? candidate = null; try { StatusText = "Поиск файла обновления..."; var resolution = await _downloads.ResolveAsync(product, new UpdateCheckResult(product.UpdateStatus, product.LatestVersion, product.LatestNormalizedVersion), _cts.Token); if (resolution.Status == DownloadCandidateStatus.Ambiguous) { var pick = Microsoft.VisualBasic.Interaction.InputBox("Найдены варианты:\n" + string.Join("\n", resolution.Candidates.Select((x,i) => $"{i + 1}. {x.FileName} ({x.Architecture ?? "?"})")) + "\nВведите номер:", "Выбор installer"); if (!int.TryParse(pick, out var index) || index < 1 || index > resolution.Candidates.Count) { StatusText = "Скачивание отменено: файл не выбран."; return; } candidate = resolution.Candidates[index - 1]; } else candidate = resolution.Candidates.SingleOrDefault(); if (candidate is null) { StatusText = resolution.Error ?? "Файл обновления не найден."; return; } var destination = _settings.DownloadDestinationKind == DownloadDestinationKind.Absolute ? _settings.DownloadDestination : Path.Combine(_appPaths.ApplicationRoot, _settings.DownloadDestination); var staging = Path.Combine(_appPaths.CacheDirectory, "Staging"); var progress = new Progress<DownloadProgress>(p => StatusText = $"{p.Status}: {p.FileName} {p.Percent?.ToString("F0") ?? "?"}%"); var result = await _downloader.DownloadAsync(candidate, staging, destination, progress, TimeSpan.FromMinutes(_settings.DownloadTimeoutMinutes), _cts.Token); if (result.Status == DownloadStatus.Completed && result.FinalPath is not null && result.Sha256 is not null) { var metadata = new InstallerMetadataService().Extract(result.FinalPath); if (metadata.Status != MetadataStatus.Success || string.IsNullOrWhiteSpace(metadata.ProductName) || new ProductNormalizer().Normalize(metadata.ProductName) != product.NormalizedName || (!string.IsNullOrWhiteSpace(product.LatestNormalizedVersion) && !string.IsNullOrWhiteSpace(metadata.ProductVersion) && new VersionComparer().Compare(VersionNormalizer.Normalize(metadata.ProductVersion), product.LatestNormalizedVersion) == VersionComparisonResult.Older)) { File.Delete(result.FinalPath); result = new(DownloadStatus.ValidationFailed, null, result.Sha256, "Metadata не подтверждает ожидаемый продукт или версию."); } else result = await DownloadService.FinalizeAsync(result.FinalPath, destination, candidate.FileName ?? "download.bin", result.Sha256, _cts.Token); } var relative = result.FinalPath is null ? null : Path.GetRelativePath(_appPaths.ApplicationRoot, result.FinalPath); await _history.SaveDownloadHistoryAsync(new(Guid.NewGuid(), product.Id, candidate.Provider, candidate.ExternalProductId, candidate.Version, candidate.FileName, candidate.Uri?.ToString(), candidate.Sha256, result.Sha256, result.Status, result.Error, started, DateTimeOffset.UtcNow, relative), CancellationToken.None); StatusText = result.Status == DownloadStatus.Completed ? $"Скачивание завершено: {result.FinalPath}" : result.Error ?? result.Status.ToString(); } catch (OperationCanceledException) { StatusText = "Скачивание отменено."; } finally { IsScanning = false; _cts.Dispose(); _cts = null; } }
    private async Task CheckAsync(IEnumerable<SoftwareProduct> list) { if (IsScanning) return; IsScanning = true; _cts = new(); try { var summary = await _batch.CheckAsync(list, true, _settings.UpdateCheckCacheHours, _settings.MaxUpdateCheckParallelism, _cts.Token); await RefreshProductsAsync(); StatusText = $"Проверка обновлений завершена: {summary.Checked}."; } catch (OperationCanceledException) { StatusText = "Проверка обновлений отменена."; } finally { IsScanning = false; _cts.Dispose(); _cts = null; } }
    private async Task SetBindingAsync(string provider, string prompt) { if (SelectedProduct is null) return; var value = Microsoft.VisualBasic.Interaction.InputBox(prompt, "Software Catalog").Trim(); if (string.IsNullOrWhiteSpace(value)) return; await _products.SetUpdateSourceAsync(new ProductUpdateSource(Guid.NewGuid(), SelectedProduct.Id, provider, value, true, true), CancellationToken.None); await RefreshProductsAsync(); StatusText = $"Привязка {provider} сохранена."; }
    private async Task ClearBindingAsync(string provider) { if (SelectedProduct is null) return; await _products.ClearUpdateSourcesAsync(SelectedProduct.Id, provider, CancellationToken.None); await RefreshProductsAsync(); StatusText = $"Привязка {provider} очищена."; }
    public event PropertyChangedEventHandler? PropertyChanged; private void OnChanged([CallerMemberName] string? name = null) => PropertyChanged?.Invoke(this, new(name));
}
public sealed class RelayCommand(Action execute) : ICommand { public event EventHandler? CanExecuteChanged { add { } remove { } } public bool CanExecute(object? parameter) => true; public void Execute(object? parameter) => execute(); }
public sealed class AsyncCommand(Func<Task> execute) : ICommand { public event EventHandler? CanExecuteChanged { add { } remove { } } public bool CanExecute(object? parameter) => true; public async void Execute(object? parameter) => await execute(); }
